package br.com.arenadev.integration.provider.notion;
import br.com.arenadev.integration.application.IntegrationConnectionService;
import br.com.arenadev.integration.application.port.IntegrationCredentialStore;
import br.com.arenadev.integration.domain.LearningPlatformProvider;
import jakarta.servlet.http.HttpSession;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.util.LinkedMultiValueMap;
import org.springframework.web.client.RestClient;
import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.Base64;import java.util.HexFormat;
@Service
public class NotionDelegatedOAuthService {
 private static final String STATE_KEY="arena.notion.oauth.state"; private final NotionOAuthSettings settings; private final IntegrationCredentialStore credentials; private final IntegrationConnectionService connections; private final String frontendUrl,encryptionKey; private final SecureRandom random=new SecureRandom(); private final RestClient oauth=RestClient.builder().baseUrl("https://api.notion.com/v1").build();
 public NotionDelegatedOAuthService(NotionOAuthSettings settings,IntegrationCredentialStore credentials,IntegrationConnectionService connections,@Value("${app.frontend-url:http://localhost:3000}") String frontendUrl,@Value("${app.integrations.credential-encryption-key:}") String encryptionKey){this.settings=settings;this.credentials=credentials;this.connections=connections;this.frontendUrl=frontendUrl.replaceAll("/+$","");this.encryptionKey=encryptionKey==null?"":encryptionKey.trim();}
 public String authorizationUrl(HttpSession session){settings.requireConfigured();if(encryptionKey.isBlank())throw new IllegalStateException("Configure APP_INTEGRATIONS_CREDENTIAL_ENCRYPTION_KEY antes de conectar o Notion.");byte[] bytes=new byte[24];random.nextBytes(bytes);String state=HexFormat.of().formatHex(bytes);session.setAttribute(STATE_KEY,state);return "https://api.notion.com/v1/oauth/authorize?owner=user&client_id="+enc(settings.clientId())+"&redirect_uri="+enc(settings.redirectUri())+"&response_type=code&state="+enc(state);}
 public CallbackResult complete(String code,String state,HttpSession session){settings.requireConfigured();Object expected=session.getAttribute(STATE_KEY);session.removeAttribute(STATE_KEY);if(!(expected instanceof String s)||!s.equals(state))throw new IllegalArgumentException("State OAuth Notion inválido ou expirado.");var form=new LinkedMultiValueMap<String,String>();form.add("grant_type","authorization_code");form.add("code",required(code,"code"));form.add("redirect_uri",settings.redirectUri());String basic=Base64.getEncoder().encodeToString((settings.clientId()+":"+settings.clientSecret()).getBytes(StandardCharsets.UTF_8));TokenResponse token=oauth.post().uri("/oauth/token").contentType(MediaType.APPLICATION_FORM_URLENCODED).header("Authorization","Basic "+basic).body(form).retrieve().body(TokenResponse.class);if(token==null||token.access_token()==null||token.access_token().isBlank())throw new IllegalStateException("Notion OAuth não retornou access token.");String workspaceId=required(token.workspace_id(),"workspace_id");String workspaceName=first(token.workspace_name(),"Workspace Notion");var c=connections.create(LearningPlatformProvider.NOTION,"Notion · "+workspaceName,workspaceId);String ref=credentials.store(c.getId(),new IntegrationCredentialStore.CredentialMaterial(token.access_token(),token.refresh_token(),null,null));connections.attachCredentialReference(c.getId(),ref);connections.activate(c.getId());return new CallbackResult(c.getId(),workspaceId,workspaceName,frontendUrl+"/?notion=connected");}
 private static String enc(String v){return URLEncoder.encode(v,StandardCharsets.UTF_8);} private static String required(String v,String f){if(v==null||v.isBlank())throw new IllegalArgumentException(f+" é obrigatório.");return v.trim();} private static String first(String...v){for(String s:v)if(s!=null&&!s.isBlank())return s.trim();return "Notion";}
 public record CallbackResult(java.util.UUID connectionId,String workspaceId,String workspaceName,String redirectUrl){} record TokenResponse(String access_token,String refresh_token,String token_type,String bot_id,String workspace_name,String workspace_icon,String workspace_id,Object owner){}
}
